import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";import{G as i,W as a}from"./chunks/assets.DeBnt35C.js";var o=JSON.parse(`{"title":"虚拟机与容器","description":"","frontmatter":{},"headers":[],"relativePath":"middleware/docker/basic/vm-container.md","filePath":"middleware/docker/basic/vm-container.md"}`),s={name:`middleware/docker/basic/vm-container.md`};function c(r,o,s,c,l,u){return n(),e(`div`,null,[...o[0]||=[t(`<h1 id="虚拟机与容器" tabindex="-1">虚拟机与容器 <a class="header-anchor" href="#虚拟机与容器" aria-label="Permalink to “虚拟机与容器”">​</a></h1><ul><li>虚拟机与容器对比</li></ul><h2 id="虚拟机" tabindex="-1">虚拟机 <a class="header-anchor" href="#虚拟机" aria-label="Permalink to “虚拟机”">​</a></h2><ul><li>虚拟机(virtual machine)就是带环境安装的一种方案。</li><li>虚拟机可以在一个操作系统里面安装另一个操作系统，例如window11里面安装ubuntu系统。</li><li>应用程序(App)对此毫无感知，因为虚拟机看上去跟真实系统一样。而对于底层系统来说，虚拟机就是一个普通文件，不需要就删掉，对其他部分毫无影响。</li></ul><h3 id="使用工具" tabindex="-1">使用工具 <a class="header-anchor" href="#使用工具" aria-label="Permalink to “使用工具”">​</a></h3><ul><li>virtualBox：<a href="https://www.virtualbox.org" target="_blank" rel="noreferrer">https://www.virtualbox.org</a></li><li>vmWare：<a href="https://www.vmware.com/products/desktop-hypervisor/workstation-and-fusion" target="_blank" rel="noreferrer">https://www.vmware.com/products/desktop-hypervisor/workstation-and-fusion</a></li></ul><h3 id="架构图" tabindex="-1">架构图 <a class="header-anchor" href="#架构图" aria-label="Permalink to “架构图”">​</a></h3><p><img src="`+i+`" alt="" width="561" height="371"></p><h3 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to “优点”">​</a></h3><ul><li>虚拟机可减少在服务器设备上的支出，可以利用一个物理服务器资源切分成多个独立的虚拟机来完成许多工作。</li><li>由于只有一台主机，因此可以利用虚拟机管理程序的集中功能高效地管理所有虚拟环境。这些系统完全相互独立，这意味着你可以在不同的虚拟机里安装不同的系统环境。</li><li>最重要的是，虚拟机与主机操作系统隔离，是进行实验和开发应用程序的安全场所。</li></ul><h3 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to “缺点”">​</a></h3><ul><li>虚拟机可能占用主机的大量系统资源，虚拟机的大小为数GB。在虚拟服务器上运行单个应用程序意味着还要运行Guest OS以及Guest OS运行所需的所有硬件的虚拟副本。这样很快就增加了很多RAM和CPU资源消耗。</li><li>迁移虚拟机上运行的应用程序的过程也可能很复杂，因为它始终附加在操作系统上。因此，必须同时迁移应用程序和操作系统。同样，在创建虚拟机时，系统管理程序会分配专用于VM的硬件资源。 不过与运行单独的实体服务器相比，这仍然是经济的。</li></ul><h2 id="容器" tabindex="-1">容器 <a class="header-anchor" href="#容器" aria-label="Permalink to “容器”">​</a></h2><ul><li>容器是一个不依赖于操作系统，运行应用程序的环境。它通过Linux的Namespaces和Cgroups技术对应用程序进程进行隔离和限制的，Namespace的作用是隔离，它让应用进程只能看到该Namespace内的世界；而Cgroups 的作用是限制分配给进程的宿主机资源。但对于宿主机来说，这些被“隔离”了的进程跟其他进程并没有太大区别。</li><li>容器只是运行在宿主机上的一种特殊的进程，多个容器之间使用的还是同一个宿主机的操作系统内核。</li></ul><h3 id="容器架构图" tabindex="-1">容器架构图 <a class="header-anchor" href="#容器架构图" aria-label="Permalink to “容器架构图”">​</a></h3><p><img src="`+a+`" alt="" width="441" height="241"></p><h2 id="对比" tabindex="-1">对比 <a class="header-anchor" href="#对比" aria-label="Permalink to “对比”">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>虚拟机</th><th>docker</th></tr></thead><tbody><tr><td>内存</td><td>大(一般&gt;1G)</td><td>小(一般&lt;500M)</td></tr><tr><td>启动速度</td><td>慢(一般&gt;1min)</td><td>快(一般&lt;10s)</td></tr><tr><td>整合程度</td><td>坏</td><td>好</td></tr></tbody></table>`,18)]])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};